import CryptoKit
import Foundation
import XCTest
@testable import BridgeyMac

/// A session recorded between two Bridgey session clients (rust/client, the core of the Windows app), checked frame
/// by frame with this app's own decoder, pairing checks, envelope tags, AES-GCM and feature decoding: what the Mac
/// would do with the same bytes. Generated by rust/client/src/vectors.rs.
final class SessionClientVectorTests: XCTestCase {
    private struct Frame {
        let from: String
        let message: PairingMessage
    }

    private struct Vector {
        let prk: Data
        let sessionKey: Data
        let code: String
        let clipboardText: String
        let frames: [Frame]

        func first(_ kind: String) throws -> PairingMessage {
            try XCTUnwrap(frames.first { $0.message.kind == kind }?.message, kind)
        }
    }

    private func load() throws -> Vector {
        let url = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("../../../protocol/test-vectors/session-client-v1.json")
            .standardizedFileURL
        let object = try XCTUnwrap(try JSONSerialization.jsonObject(with: Data(contentsOf: url)) as? [String: Any])
        let rawFrames = try XCTUnwrap(object["frames"] as? [[String: Any]])
        var frames: [Frame] = []
        for raw in rawFrames {
            let from = try XCTUnwrap(raw["from"] as? String)
            let line = try XCTUnwrap(raw["line"] as? String)
            frames.append(Frame(from: from, message: try decodeProtocolMessage(Data(line.utf8))))
        }
        return Vector(
            prk: try XCTUnwrap(Data(base64Encoded: try XCTUnwrap(object["prk"] as? String))),
            sessionKey: try XCTUnwrap(Data(base64Encoded: try XCTUnwrap(object["sessionKey"] as? String))),
            code: try XCTUnwrap(object["code"] as? String),
            clipboardText: try XCTUnwrap(object["clipboardText"] as? String),
            frames: frames
        )
    }

    func testFirstPairingCommitsRevealsAndShowsTheSameCode() throws {
        let vector = try load()
        let offer = try vector.first("pairing.offer")
        let answer = try vector.first("pairing.answer")
        let reveal = try vector.first("pairing.reveal")
        XCTAssertEqual(offer.protocolVersion, 2)
        XCTAssertEqual(answer.protocolVersion, 2)
        XCTAssertNil(offer.publicKey)
        let commitment = try XCTUnwrap(offer.commitment)
        let initiatorKey = try XCTUnwrap(reveal.publicKey)
        let responderKey = try XCTUnwrap(answer.publicKey)
        XCTAssertTrue(SessionSecurity.commitmentMatches(commitment, sessionID: offer.sessionId, publicKey: initiatorKey))
        XCTAssertEqual(SessionSecurity.sasCode(prk: vector.prk, initiatorKey: initiatorKey, responderKey: responderKey), vector.code)
        let info = Data("bridgey-pairing-v1".utf8) + Data([1])
        let expanded = Data(HMAC<SHA256>.authenticationCode(for: info, using: SymmetricKey(data: vector.prk)))
        XCTAssertEqual(expanded, vector.sessionKey)
    }

    func testBothConfirmationsVerifyAsTheMacChecksThem() throws {
        let vector = try load()
        let offer = try vector.first("pairing.offer")
        let answer = try vector.first("pairing.answer")
        let reveal = try vector.first("pairing.reveal")
        let initiatorID = try XCTUnwrap(offer.deviceId)
        let responderID = try XCTUnwrap(answer.deviceId)
        let initiatorKey = try XCTUnwrap(reveal.publicKey)
        let responderKey = try XCTUnwrap(answer.publicKey)
        let fields = ["bridgey-auth-v1", offer.sessionId, initiatorID, responderID, initiatorKey, responderKey]
        let transcript = Data(fields.joined(separator: "\u{0}").utf8)
        let confirms = vector.frames.map(\.message).filter { $0.kind == "pairing.confirm" }
        XCTAssertEqual(confirms.count, 2)
        for confirm in confirms {
            let deviceID = try XCTUnwrap(confirm.deviceId)
            let identity = try XCTUnwrap(confirm.identityKey)
            let proof = try XCTUnwrap(confirm.proof)
            let signatureText = try XCTUnwrap(confirm.signature)
            XCTAssertTrue(verifyConfirmationProof(proof, key: vector.sessionKey, sessionID: offer.sessionId, deviceID: deviceID, identityKey: identity))
            let publicKey = try P256.Signing.PublicKey(x963Representation: try XCTUnwrap(Data(base64Encoded: identity)))
            let signature = try P256.Signing.ECDSASignature(derRepresentation: try XCTUnwrap(Data(base64Encoded: signatureText)))
            XCTAssertTrue(publicKey.isValidSignature(signature, for: transcript))
        }
    }

    func testEveryFrameAfterPairingIsTaggedAndOpens() throws {
        let vector = try load()
        let initiatorID = try XCTUnwrap(try vector.first("pairing.offer").deviceId)
        let responderID = try XCTUnwrap(try vector.first("pairing.answer").deviceId)
        let envelopeKey = SessionSecurity.envelopeKey(sessionKey: vector.sessionKey)
        var featureMaps = 0
        var clipboardMessageID: String?
        for frame in vector.frames where !frame.message.kind.hasPrefix("pairing.") {
            let sender = frame.from == "initiator" ? initiatorID : responderID
            XCTAssertTrue(SessionSecurity.tagMatches(envelopeKey: envelopeKey, senderDeviceID: sender, message: frame.message), frame.message.kind)
            switch frame.message.kind {
            case "features.update":
                let plaintext = try decrypt(nonce: try XCTUnwrap(frame.message.nonce), ciphertext: try XCTUnwrap(frame.message.ciphertext), key: vector.sessionKey)
                guard case let .state(features, _) = decodeFeatureState(plaintext) else {
                    XCTFail("features.update decodes")
                    continue
                }
                XCTAssertEqual(features[.clipboard], true)
                featureMaps += 1
            case "clipboard.update":
                let plaintext = try decrypt(nonce: try XCTUnwrap(frame.message.nonce), ciphertext: try XCTUnwrap(frame.message.ciphertext), key: vector.sessionKey)
                XCTAssertEqual(String(data: plaintext, encoding: .utf8), vector.clipboardText)
                clipboardMessageID = frame.message.messageId
            default:
                break
            }
        }
        XCTAssertEqual(featureMaps, 2)
        XCTAssertNotNil(clipboardMessageID)
        XCTAssertEqual(try vector.first("clipboard.ack").messageId, clipboardMessageID)
    }
}
